Here is the recipe JSON:
{
  "recipe_name": "Idli",
  "ingredients": [
    "2 cups idli rice",
    "1 cup urad dal",
    "1/2 cup fenugreek seeds",
    "1/2 teaspoon salt",
    "water as needed"
  ],
  "steps": [
    {
      "step_number": 1,
      "instruction": "Soak the idli rice, urad dal, and fenugreek seeds in water for 4-5 hours",
      "time": "4-5 hours",
      "tip": "Use a large bowl to soak the ingredients"
    },
    {
      "step_number": 2,
      "instruction": "Grind the soaked ingredients into a smooth batter",
      "time": "30 minutes",
      "tip": "Use a wet grinder or mixer to grind the ingredients"
    },
    {
      "step_number": 3,
      "instruction": "Add salt to the batter and mix well",
      "time": "5 minutes",
      "tip": "Use a spoon to mix the batter"
    },
    {
      "step_number": 4,
      "instruction": "Ferment the batter overnight or for 8-10 hours",
      "time": "8-10 hours",
      "tip": "Keep the batter in a warm place to ferment"
    },
    {
      "step_number": 5,
      "instruction": "Grease the idli molds with oil or ghee",
      "time": "5 minutes",
      "tip": "Use a brush to grease the molds"
    },
    {
      "step_number": 6,
      "instruction": "Pour the fermented batter into the idli molds",
      "time": "5 minutes",
      "tip": "Fill the molds 3/4th with the batter"
    },
    {
      "step_number": 7,
      "instruction": "Steam the idlis for 15-20 minutes",
      "time": "15-20 minutes",
      "tip": "Use a steamer or idli cooker to steam the idlis"
    }
  ]
}
